function envelopeFor(operation: string) {
  return FIXTURES.envelopes[operation.replace(/\./g, '_')]
}

function stub(bodies: unknown[]) {
  const calls: Request[] = []
  let index = 0
  const fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    calls.push(new Request(typeof input === 'string' ? input : String(input), init))
    const body = bodies[Math.min(index, bodies.length - 1)]
    index += 1
    return new Response(JSON.stringify(body), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    })
  }
  return { calls, fetch: fetch as unknown as typeof globalThis.fetch }
}

for (const entry of CALLS) {
  test(`${entry.operation} maps its request`, async () => {
    const { calls, fetch } = stub([envelopeFor(entry.operation)])
    const client = new ZelfAPIClient({ apiKey: KEY, maxRetries: 0, fetch })

    const result = await entry.call(client)

    assert.equal(calls.length, 1, entry.operation)
    const request = calls[0]!
    const url = new URL(request.url)
    assert.equal(request.method, entry.method)
    assert.equal(url.pathname, entry.path)
    for (const [key, values] of Object.entries(entry.query)) {
      assert.deepEqual(
        url.searchParams.getAll(key),
        values,
        `${entry.operation} sent a wrong ?${key}`,
      )
    }
    if (entry.body.length > 0) {
      const sent = JSON.parse(await request.text())
      for (const key of entry.body) {
        assert.ok(key in sent, `${entry.operation} dropped body field ${key}`)
      }
    }
    if (entry.cardinality === 'page') {
      assert.ok(result instanceof Page)
    } else if (entry.cardinality === 'list') {
      assert.ok(Array.isArray(result))
    }
  })
}

test('the api key header is sent once', async () => {
  // A caller's own key header must not replace or duplicate the client's.
  const entry = CALLS[0]!
  const { calls, fetch } = stub([envelopeFor(entry.operation)])
  const client = new ZelfAPIClient({
    apiKey: KEY,
    maxRetries: 0,
    fetch,
    defaultHeaders: { 'X-API-Key': 'sk_zelf_' + '9'.repeat(64) },
  })

  await entry.call(client)

  assert.equal(calls[0]!.headers.get('x-api-key'), KEY)
})

for (const entry of CALLS.filter((row) => row.cardinality === 'page')) {
  test(`${entry.operation} walks its pages`, async () => {
    const first = { ...envelopeFor(entry.operation), next: 2 }
    const second = { ...envelopeFor(entry.operation), page: 2, next: null }
    const { calls, fetch } = stub([first, second])
    const client = new ZelfAPIClient({ apiKey: KEY, maxRetries: 0, fetch })

    const page = (await entry.call(client)) as Page<unknown>
    const rows: unknown[] = []
    for await (const row of page.autoPaging({ maxPages: 2 })) {
      rows.push(row)
    }

    assert.equal(calls.length, 2, entry.operation)
    assert.ok(rows.length > 0)
  })
}
